css:
img{border-radius:0;box-shadow:none;outline:1px solid #cabfa6;outline-offset:10px}
/* 色面のマット（二重角丸） */
.panel{background:#36c29f;border-radius:28px;padding:20px}
.panel img{display:block;width:100%;border-radius:14px}
/* 主張しない外周 */
.orbit{position:absolute;inset:-22px;border:2px dotted #cbb7b3;border-radius:50%;z-index:0}
